<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount } from 'vue';
import type { DirectoryEntry, Person } from '@zhijiao/shared';
import { client, directory, selfPersonId, vaultState, base } from '../state';
import Avatar from './Avatar.vue'; import Icon from './Icon.vue';
const props = defineProps<{ selected?: string[]; multiple?: boolean; allowEmpty?: boolean; initialDrafts?: Person[] }>();
const emit = defineEmits<{ confirm: [ids: string[], drafts: Person[]]; cancel: [] }>();
const panel = ref<HTMLElement>(); let previousFocus: Element | null = null;
const selected = ref<string[]>([...(props.selected ?? [])]); const query = ref(''); const drafts = ref<Person[]>([...(props.initialDrafts ?? [])]); const showSelected = ref(false); const focused = ref(false); const keyboardOffset = ref(0); const viewportHeight = ref(window.innerHeight);
const rows = computed(() => { void directory.value; const found = client.value?.searchPeople(query.value).entries ?? []; const local = drafts.value.filter(person => !query.value || person.displayName.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())).map(person => ({ ...person, kind: 'directory' as const, personId: person.id, aliases: [], distinguishing: '本次新建，保存记录后入库' })); return [...found, ...local].slice(0, query.value ? 100 : 5); });
const choices = computed(() => selected.value.map(id => directory.value.find(person => person.personId === id) ?? drafts.value.find(person => person.id === id)).filter(Boolean));
function toggle(person: DirectoryEntry) { if (!props.multiple) { emit('confirm', [person.personId], drafts.value.filter(draft => draft.id === person.personId)); return; } selected.value = selected.value.includes(person.personId) ? selected.value.filter(id => id !== person.personId) : [...selected.value, person.personId]; }
function create() { const displayName = query.value.trim(); if (!displayName) return; const person: Person = { ...base(), kind: 'person', displayName, status: 'active' }; drafts.value.push(person); query.value = ''; if (props.multiple) selected.value.push(person.id); else emit('confirm', [person.id], [person]); }
function confirm() { if (!selected.value.length && !props.allowEmpty) return; emit('confirm', selected.value, drafts.value.filter(person => selected.value.includes(person.id))); }
function resize() { const viewport = window.visualViewport; viewportHeight.value = viewport?.height ?? window.innerHeight; keyboardOffset.value = viewport ? Math.max(0, window.innerHeight - viewport.height - viewport.offsetTop) : 0; }
function key(event: KeyboardEvent) { if (event.key === 'Escape') { event.preventDefault(); emit('cancel'); return; } if (event.key !== 'Tab' || !panel.value) return; const items = Array.from(panel.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled)')); if (!items.length) return; if (event.shiftKey && document.activeElement === items[0]) { event.preventDefault(); items[items.length-1].focus(); } else if (!event.shiftKey && document.activeElement === items[items.length-1]) { event.preventDefault(); items[0].focus(); } }
onMounted(() => { previousFocus = document.activeElement; panel.value?.focus(); resize(); window.visualViewport?.addEventListener('resize', resize); window.visualViewport?.addEventListener('scroll', resize); document.addEventListener('keydown', key); });
onBeforeUnmount(() => { window.visualViewport?.removeEventListener('resize', resize); window.visualViewport?.removeEventListener('scroll', resize); document.removeEventListener('keydown', key); query.value = ''; drafts.value = []; if (previousFocus instanceof HTMLElement && previousFocus.isConnected) previousFocus.focus(); });
</script>
<template><Teleport to="body"><div class="picker-overlay" @click.self="emit('cancel')"><section ref="panel" tabindex="-1" class="person-picker" :class="{ expanded: focused }" :style="{ '--keyboard-bottom': `${keyboardOffset}px`, '--picker-height': `${viewportHeight - 12}px` }" role="dialog" aria-modal="true" aria-label="选择人物"><div class="sheet-handle" /><header class="picker-heading"><h2>{{ multiple ? '选择参与的人' : '选择人物' }}</h2><button class="text-button" @click="emit('cancel')">取消</button></header><label class="search-input"><Icon name="search" /><input v-model="query" placeholder="姓名、昵称、拼音或首字母" aria-label="搜索人物" @focus="focused = true" @blur="focused = false"><button v-if="query" class="icon-button" aria-label="清空搜索" @click="query = ''"><Icon name="close" :size="16" /></button></label><p v-if="!vaultState?.directoryComplete" class="notice">人物目录尚未完整同步，当前搜索仅覆盖已下载人物。</p><div v-if="selected.length && multiple" class="selection-summary"><button v-for="person in choices.slice(0, 2)" :key="person!.id" class="chip" @click="selected = selected.filter(id => id !== ('personId' in person! ? person!.personId : person!.id))">{{ person!.displayName }} <Icon name="close" :size="12" /></button><button v-if="selected.length > 2" class="chip" @click="showSelected = !showSelected">+{{ selected.length - 2 }}</button><button class="text-button" @click="showSelected = !showSelected">{{ showSelected ? '收起' : '查看已选' }}</button></div><div v-if="showSelected" class="selected-list"><button v-for="person in choices" :key="person!.id" @click="selected = selected.filter(id => id !== ('personId' in person! ? person!.personId : person!.id))">{{ person!.displayName }} <Icon name="close" :size="16" /></button></div><div class="picker-results"><p class="eyebrow">{{ query ? '搜索结果' : '常用人物 · 最多 5 人' }}</p><button v-for="person in rows" :key="person.personId" class="person-row" :class="{ selected: selected.includes(person.personId) }" @click="toggle(person)"><Avatar :name="person.displayName" :avatar="person.avatar" /><span><strong>{{ person.displayName }}</strong><small>{{ person.personId === selfPersonId ? '账号本人' : person.distinguishing || (person.status === 'archived' ? '已归档' : '尚未填写辨识信息') }}</small></span><span v-if="multiple" class="selection-circle"><Icon v-if="selected.includes(person.personId)" name="check" :size="14" /></span><Icon v-else name="arrow" :size="16" /></button><div v-if="!rows.length" class="empty compact"><p>{{ query ? (vaultState?.directoryComplete ? '没有找到匹配人物' : '已下载的目录中暂未找到') : '还没有人物记录' }}</p><button v-if="query.trim()" class="button secondary" @click="create"><Icon name="plus" :size="16" />新建「{{ query.trim() }}」并选中</button><p v-if="query.trim() && !vaultState?.directoryComplete" class="muted">目录同步后可能出现同名人物，请留意重复。</p></div></div><footer v-if="multiple" class="picker-footer"><button v-if="allowEmpty && selected.length" type="button" class="text-button block" @click="selected = []">取消全部关联</button><button class="button primary full" :disabled="!selected.length && !allowEmpty" @click="confirm">确认（{{ selected.length }}）</button></footer></section></div></Teleport></template>
